package DeliveryUAV_Model {

    requirement def REQ_SAFE_005 {
        doc /* The system shall deploy the ballistic recovery parachute within 0.5 seconds of detecting a critical propulsion subsystem failure during flight. */
    }

    requirement def REQ_FUNC_001 {
        doc /* The system shall provide structural containment, flight capabilities, and integrate all subsystems. */
    }

    port def SignalPort { }

    part def PropulsionSystem {
        satisfy requirement REQ_FUNC_001;
        port out propStatus : SignalPort;
        attribute thrust : Real = 150.0 [N];
    }

    part def ParachuteSystem {
        satisfy requirement REQ_SAFE_005;
        port in chuteCmd : SignalPort;
        attribute parachuteArea : Real = 3.0 [sq_m];
    }

    part def FlightController {
        satisfy requirement REQ_FUNC_001;
        port in overrideCmd : SignalPort;
        attribute controlFrequency : Real = 400.0 [Hz];
    }

    part def SafetyMonitor {
        satisfy requirement REQ_SAFE_005;
        port in propStatus : SignalPort;
        port out chuteCmd : SignalPort;
        port out overrideCmd : SignalPort;

        attribute parachuteDeployTime : Real = 0.5 [s];
        attribute propulsionCriticalFailure : Boolean = false;

        action def DeployParachuteAction { }

        state def SafetyMonitorStateMachine {
            state SafetyNominal;
            state SafetyCritical {
                entry DeployParachuteAction;
            }
            transition SafetyNominal to SafetyCritical if propulsionCriticalFailure == true;
        }
    }

    part def DeliveryUAVSystem {
        satisfy requirement REQ_FUNC_001;
        port out telemetry : SignalPort;
        attribute systemMass : Real = 25.0 [kg];

        part propSys : PropulsionSystem;
        part chuteSys : ParachuteSystem;
        part fc : FlightController;
        part monitor : SafetyMonitor;

        connect propSys.propStatus to monitor.propStatus;
        connect monitor.chuteCmd to chuteSys.chuteCmd;
        connect monitor.overrideCmd to fc.overrideCmd;
    }
}
```

